    public static function validate(): void
    {
        $keys = array_keys(self::WATAK_BAYI);
        sort($keys);
        if ($keys !== self::EXPECTED_NEPTU) {
            throw new RuntimeException('WatakBayi: neptu keys mismatch');
        }
        foreach (self::WATAK_BAYI as $k => $v) {
            if (!isset($v['sumber']) || !is_string($v['sumber']) || trim($v['sumber']) === '') {
                throw new RuntimeException('WatakBayi: missing sumber for ' . $k);
            }
            if (!isset($v['makna']) || !is_string($v['makna']) || trim($v['makna']) === '') {
                throw new RuntimeException('WatakBayi: missing makna for ' . $k);
            }
        }
    }

    public static function get(int $totalNeptu): array
    {
        if (!isset(self::WATAK_BAYI[$totalNeptu])) {
            throw new InvalidArgumentException('WatakBayi: unknown totalNeptu ' . $totalNeptu);
        }
        return self::WATAK_BAYI[$totalNeptu];
    }
